library(readr)
library(dplyr)
library(tidyr)
library(labelled)

# Function to map NVQ codes to 5-level NVQ scheme
# academic and vocational NVQ variables have values:
# -9 Refused, -8 Missing info, -1 Not applicable, 0 Entry Level, 1-5 NVQ levels, 95 other, 96 none
nvq_to_tier <- function(x){
  case_when(
    is.na(x) ~ NA_real_,
    x == -9 ~ -9,      # Refused
    x == -8 ~ -8,      # Missing info
    x == -1 ~ -1,      # Not applicable
    x == 0  ~ 2,       # Entry level -> tier 2
    x >= 1 & x <= 3 ~ 1,  # NVQ1-3 -> tier 1
    x >= 4 & x <= 5 ~ 0,  # NVQ4-5 -> tier 0
    x == 95 ~ 3,       # Other qualifications -> tier 3
    x == 96 ~ 4        # None of these -> tier 4
  )
}

# Load all files
wave_one <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t", col_types = cols(.default = "guess"))
wave_four <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t", col_types = cols(.default = "guess"))
ns8_main <- read_delim("data/input/ns8_2015_main_interview.tab", delim = "\t", col_types = cols(.default = "guess"))
ns8_derived <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t", col_types = cols(.default = "guess"))
ns9_main <- read_delim("data/input/ns9_2022_main_interview.tab", delim = "\t", col_types = cols(.default = "guess"))
ns9_derived <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t", col_types = cols(.default = "guess"))

# Merge all datasets by NSID using full_join
merged <- wave_one %>%
  full_join(wave_four, by = "NSID") %>%
  full_join(ns8_main, by = "NSID") %>%
  full_join(ns8_derived, by = "NSID") %>%
  full_join(ns9_main, by = "NSID") %>%
  full_join(ns9_derived, by = "NSID")

# ---- educ25 (age 25, collapsed 5-level NVQ scheme) ----
# Map academic NVQ variable
acad_tier25 <- nvq_to_tier(merged$W8DHANVQH)

# Define mapping for each vocational tick box to NVQ tier
# Based on variable names; see metadata for mapping
voc_vars <- c("W8VCQU0A","W8VCQU0B","W8VCQU0C","W8VCQU0D","W8VCQU0E","W8VCQU0F","W8VCQU0G","W8VCQU0H","W8VCQU0I","W8VCQU0J","W8VCQU0K","W8VCQU0L","W8VCQU0M","W8VCQU0N","W8VCQU0O")
# Map each variable to a tier value (0-4) if Yes, otherwise NA
# We approximate tiers: Youth training, Key Skills, Basic skills, Entry level quals, Modern apprenticeship, RSA/OCR, City & Guilds, GNVQ/GSVQ, NVQ Level1-2, NVQ Level3-5, HNC/HND, ONC/OND, BTEC/BEC..., SCOTVEC, Other vocational
