    if(any(tiers==-9)) return(-9)
    if(any(tiers==-8)) return(-8)
    if(any(tiers==-1)) return(-1)
    return(NA_real_)
  }
})

# Combine academic and vocational tiers: choose best (min numeric) among 0-4; if none, keep most severe missing code
