    v
  } else {
    # both missing; keep most severe negative code
    if(!is.na(a) && a %in% c(-9,-8,-1,-3,-2)) return(a)
    if(!is.na(v) && v %in% c(-9,-8,-1,-3,-2)) return(v)
    return(NA_real_)
  }
}, acad_tier32, voc_tier32)

