  subs_values <- row
  # Check for any -1
  if(any(subs_values==-1)) return(-1)
  # Check if all substantive are No (2) and no missing/-3/-9/-2
  if(all(subs_values==2) && all(!is.na(subs_values))){
    return(19) # None of these qualifications
  }
  # Check for missing or -3
  if(any(is.na(subs_values) | subs_values==-3)) return(-3)
  # Find first Yes (1)
  first_yes <- which(subs_values==1)[1]
  if(is.na(first_yes)){
    # No Yes but not all No? Might be mixture of No and missing? handled earlier
    return(-3)
  } else {
    return(first_yes) # integer code
  }
})
# Convert to factor with labels
acad_labels <- sapply(acad_vars, function(v){
  lbl <- attr(merged[[v]], "label")
  if(is.null(lbl)) lbl <- v
  sub(lbl, "^Academic qualifications gained - ", "")
})
acad_labels <- c(acad_labels, "None of these qualifications")
educadtl32_f <- factor(educadtl32, levels = c(1:19, -8,-9,-2,-1,-3), labels = c(acad_labels, "Don’t know", "Refused", "No answer", "Not applicable", "Not asked at fieldwork stage"))

# ---- educvdtl32 (detailed vocational qualifications) ----
# Define vocational variable order
voc_vars32 <- paste0("W9VCQU0", LETTERS[1:21]) # A to U
educvdtl32 <- apply(merged %>% select(all_of(voc_vars32)), 1, function(row){
  subs_values <- row
  # Non-substantive tick-boxes: -3 (Don’t know), -9 (Refused)
  if(any(subs_values==-1)) return(-1)
  if(all(subs_values==2) && all(!is.na(subs_values))){
    return(21) # None of these qualifications
  }
  if(any(is.na(subs_values) | subs_values==-3)) return(-3)
  first_yes <- which(subs_values==1)[1]
  if(is.na(first_yes)){
    return(-3)
  } else {
    return(first_yes)
  }
})
# Labels
voc_labels <- sapply(voc_vars32, function(v){
  lbl <- attr(merged[[v]], "label")
  if(is.null(lbl)) lbl <- v
  sub(lbl, "^Vocational qualifications gained - ", "")
})
voc_labels <- c(voc_labels, "None of these qualifications")
educvdtl32_f <- factor(educvdtl32, levels = c(1:21, -8,-9,-2,-1,-3), labels = c(voc_labels, "Don’t know", "Refused", "No answer", "Not applicable", "Not asked at fieldwork stage"))

# ---- Prepare final dataset ----
final_df <- merged %>% select(NSID) %>%
  mutate(
    educ25 = educ25,
    educ32 = educ32,
    educadtl32 = educadtl32_f,
    educvdtl32 = educvdtl32_f
  )

# Write CSV
write_csv(final_df, "data/output/cleaned_data.csv")
