# ---------- educadtl32 (detailed academic qualifications) ----------
acad_vars <- paste0("W9ACQU0", LETTERS[1:19]) # A-S
educadtl32_raw <- apply(merged %>% select(all_of(acad_vars)), 1, function(row){
