adac_label_vec <- as.vector(acad_labels_map[acad_vars])
levels_adtl <- c(1:19, -8,-9,-2,-1,-3)
labels_adtl <- c(adac_label_vec, "Don’t know", "Refused", "No answer", "Not applicable", "Not asked at fieldwork stage")
