  W8VCQU0B = 1, # Key Skills
  W8VCQU0C = 1, # Basic skills
  W8VCQU0D = 2, # Entry level qualifications (Wales)
  W8VCQU0E = 1, # Modern apprenticeship/trade apprenticeship
  W8VCQU0F = 1, # RSA/OCR/Clerical and commercial qualifications
  W8VCQU0G = 1, # City and Guilds Certificate
  W8VCQU0H = 1, # GNVQ/GSVQ
  W8VCQU0I = 1, # NVQ/SVQ - Level 1 - 2
  W8VCQU0J = 0, # NVQ/SVQ - Level 3 - 5
  W8VCQU0K = 0, # HNC/HND
  W8VCQU0L = 0, # ONC/OND
  W8VCQU0M = 0, # BTEC/BEC/TEC/EdExcel/LQL
  W8VCQU0N = 0, # SCOTVEC, SCOTEC or SCOTBEC
  W8VCQU0O = 0  # Other vocational, technical or professional
)

# Compute vocational tier per person: take highest tier (lowest numeric) among Yes entries
voc_tier25_vec <- apply(merged %>% select(all_of(voc_vars)), 1, function(row){
  # For each variable, check if Yes (1) and map tier
  tiers <- sapply(seq_along(row), function(i){
    val <- row[i]
    if(is.na(val)) return(NA_real_)
