  valid <- tiers[tiers %in% 0:4]
  if(length(valid)>0){
    min(valid)  # best qualification
  } else {
    # No valid qualification; preserve most severe missing code if present
    if(any(tiers==-9)) return(-9)
    if(any(tiers==-8)) return(-8)
    if(any(tiers==-1)) return(-1)
    return(NA_real_)
  }
})

# Combine academic and vocational tiers: choose best (min numeric) among 0-4; if none, keep most severe missing code
educ25 <- mapply(function(a,v){
  # a and v may be NA or negative codes
  # Extract valid tiers
  vals <- c(a, v)
  valid <- vals[vals %in% 0:4]
  if(length(valid)>0){
    min(valid)
  } else {
    # No valid tier, keep most severe missing code
    if(any(vals==-9)) return(-9)
    if(any(vals==-8)) return(-8)
    if(any(vals==-1)) return(-1)
    return(NA_real_)
  }
}, acad_tier25, voc_tier25_vec)

# ---- educ32 (age 32, collapsed 5-level NVQ scheme) ----
# Map academic NVQ
acad_tier32 <- nvq_to_tier(merged$W9DANVQH)
# Map vocational NVQ
voc_tier32 <- nvq_to_tier(merged$W9DVNVQH)
# Combine: choose best tier among valid; if one missing and other valid use that; if both missing keep the one with higher severity
educ32 <- mapply(function(a,v){
