# Function to map NVQ codes to 5-level NVQ scheme
# academic and vocational NVQ variables have values:
# -9 Refused, -8 Missing info, -1 Not applicable, 0 Entry Level, 1-5 NVQ levels, 95 other, 96 none
nvq_to_tier <- function(x){
  case_when(
    is.na(x) ~ NA_real_,
    x == -9 ~ -9,      # Refused
    x == -8 ~ -8,      # Missing info
    x == -1 ~ -1,      # Not applicable
    x == 0  ~ 2,       # Entry level -> tier 2
    x >= 1 & x <= 3 ~ 1,  # NVQ1-3 -> tier 1
    x >= 4 & x <= 5 ~ 0,  # NVQ4-5 -> tier 0
    x == 95 ~ 3,       # Other qualifications -> tier 3
    x == 96 ~ 4        # None of these -> tier 4
  )
}

# Load all files
wave_one <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t", col_types = cols(.default = "guess"))
wave_four <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t", col_types = cols(.default = "guess"))
ns8_main <- read_delim("data/input/ns8_2015_main_interview.tab", delim = "\t", col_types = cols(.default = "guess"))
