ns9_main <- read_delim("data/input/ns9_2022_main_interview.tab", delim = "\t", col_types = cols(.default = "guess"))
ns9_derived <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t", col_types = cols(.default = "guess"))

